/** The setup code is generated by Core and is valid for ten minutes. */
export function setupConfirmationEmail(code: string): {
  subject: string
  text: string
  html: string
} {
  if (!/^\d{6}$/u.test(code)) throw new Error('Invalid setup confirmation code')

  return {
    subject: 'Bubllio · Επιβεβαίωση αποστολής email / Email setup confirmation',
    text: [
      'Bubllio / Core',
      '',
      'Επιβεβαίωση αποστολής email',
      `Ο κωδικός σου: ${code}`,
      'Ισχύει για 10 λεπτά. Πληκτρολόγησέ τον στη σελίδα ρύθμισης του Bubllio.',
      'Αν δεν ξεκίνησες εσύ αυτή τη ρύθμιση, αγνόησε το μήνυμα.',
      '',
      'Email setup confirmation',
      `Your code: ${code}`,
      'Valid for 10 minutes. Enter it on the Bubllio setup page.',
      'If you did not start this setup, ignore this message.',
    ].join('\n'),
    html: `<!doctype html>
<html lang="el"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;background:#f7f8fa;font-family:Inter,Arial,sans-serif;color:#0f1f38">
  <div style="display:none;max-height:0;overflow:hidden">Ο κωδικός επιβεβαίωσης της αποστολής email λήγει σε 10 λεπτά.</div>
  <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#f7f8fa"><tr><td align="center" style="padding:32px 16px">
    <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="max-width:560px;background:#fff;border:1px solid #dce3ef;border-radius:8px">
      <tr><td style="padding:26px 32px;background:#005bef;color:#fff;font-size:24px;font-weight:800">bubllio <span style="font-size:14px;font-weight:500">/ core</span></td></tr>
      <tr><td style="padding:32px 32px 8px"><h1 style="margin:0;font-size:26px;line-height:1.3">Επιβεβαίωση αποστολής email</h1><p style="font-size:16px;line-height:1.6">Πληκτρολόγησε αυτόν τον κωδικό στη σελίδα ρύθμισης του Bubllio:</p></td></tr>
      <tr><td style="padding:8px 32px 24px"><p style="margin:0;padding:20px;background:#eaf2ff;border-radius:8px;text-align:center;font-size:32px;font-weight:800;letter-spacing:6px;color:#0f1f38">${code}</p><p style="font-size:14px;line-height:1.6">Ισχύει για <strong>10 λεπτά</strong>. Αν δεν ξεκίνησες εσύ αυτή τη ρύθμιση, αγνόησε το μήνυμα.</p></td></tr>
      <tr><td style="padding:0 32px 32px;border-top:1px solid #dce3ef"><p style="font-size:14px;line-height:1.6"><strong>Email setup confirmation</strong><br>Enter the code above on the Bubllio setup page. It expires in 10 minutes. If you did not start this setup, ignore this message.</p></td></tr>
    </table>
  </td></tr></table>
</body></html>`,
  }
}
